  /**
   * usuarioActions::executeAddSyncMail()
   * funcionalidad asociar una cuenta de correo a un usuario del sistema para sincronizar los correos electronicos
   * @return
  */
  public function executeAddSyncMail()
  {
    $currentForm = "SEGURIDAD_ASOCIAR_MAIL_ACCOUNT";
    $this->verificaPrilegioCerrar($currentForm);
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');    
    //************************************************************************************************
    $domains_config = simad_util::readConfigFileApp(['domains_enable']);
    $this->domains_enable = array();
    if($domains_config != null && isset($domains_config['domains_enable'])){
      $this->domains_enable = preg_split("/[,]+/", $domains_config['domains_enable'], -1, PREG_SPLIT_NO_EMPTY);
    }
    //************************************************************************************************
    $userselected_id = trim($this->getRequestParameter('usuario_id')) ? trim($this->getRequestParameter('usuario_id')) : null;
    $this->user_selected = UsuarioPeer::retrieveByPK($userselected_id);
    $this->email_account = new EmailAccount();
  }

  /**
   * usuarioActions::executeUpdateSyncEmail()
   * funcionalidad asociar una cuenta de correo a un usuario del sistema para sincronizar los correos electronicos
   * @return
   */
  public function executeUpdateSyncEmail()
  {
    $currentForm = "SEGURIDAD_ASOCIAR_MAIL_ACCOUNT";
    $this->verificaPrilegioCerrar($currentForm);
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');    
    //************************************************************************************************
    $userselected_id = trim($this->getRequestParameter('usuario_id')) ? trim($this->getRequestParameter('usuario_id')) : null;
    $emailproviderconfig_id = trim($this->getRequestParameter('emailproviderconfig_id')) ? trim($this->getRequestParameter('emailproviderconfig_id')) : null;
    $account_login = trim($this->getRequestParameter('account_login')) ? trim($this->getRequestParameter('account_login')) : null;
    //$metodo_autenticacion = trim($this->getRequestParameter('metodo_autenticacion')) ? trim($this->getRequestParameter('metodo_autenticacion')) : null;
    $user_selected = UsuarioPeer::retrieveByPK($userselected_id);
    $account_domain = substr(strrchr($account_login, "@"), 1);
    //************************************************************************************************
    if ($user_selected == null) {
      $this->getUser()->setFlash('messages_error', 'Ocurrio un error, los parametros enviados no son validos');
      return $this->redirect($this->getRequest()->getScriptName() . '/usuario/addSyncMail?usuario_id=' . $userselected_id);
    }    
    //************************************************************************************************
    if (!filter_var($account_login, FILTER_VALIDATE_EMAIL)) {
        $this->getUser()->setFlash('messages_error', 'Ocurrio un error, La cuenta de correo no es valida');
        return $this->redirect($this->getRequest()->getScriptName() . '/usuario/addSyncMail?usuario_id=' . $userselected_id);
    }
    //************************************************************************************************
    $domains_config = simad_util::readConfigFileApp(['domains_enable']);
    $domains_enable = array();
    if($domains_config != null && isset($domains_config['domains_enable'])){
      $domains_enable = preg_split("/[,]+/", $domains_config['domains_enable'], -1, PREG_SPLIT_NO_EMPTY);
    }
    //************************************************************************************************
    if (!in_array(strtolower($account_domain), array_map('strtolower', $domains_enable))) {
        $this->getUser()->setFlash('messages_error', 'Ocurrio un error, El dominio de la cuenta de correo no esta permitido');
        return $this->redirect($this->getRequest()->getScriptName() . '/usuario/addSyncMail?usuario_id=' . $userselected_id);
    }
    //************************************************************************************************
    if(EmailAccountPeer::AddUserEmailExist($account_login,$user_selected->getPrimaryKey())){
      $this->getUser()->setFlash('messages_error', 'Ocurrio un error, El usuario ya tiene asociada esta cuenta de correo');
      return $this->redirect($this->getRequest()->getScriptName() . '/usuario/addSyncMail?usuario_id=' . $userselected_id);
    }
    //************************************************************************************************
    $email_account = new EmailAccount();
    $email_account->setUsuarioId($user_selected->getPrimaryKey());
    $email_account->setEmailproviderconfigId($emailproviderconfig_id);
    $email_account->setAccountLogin($account_login);
    //$email_account->setAuthProvider($metodo_autenticacion);
    $email_account->setFechaCreacion(date("Y-m-d G:i:s"));
    $email_account->setFechaModificacion(date("Y-m-d G:i:s"));
    $email_account->setEsActual(0);
    $email_account->save();
    //************************************************************************************************
    AuditLogPeer::guardarAuditoriaLite(EmailAccountPeer::getOMClass(),new EmailAccount(),$email_account,ModulesEnable::Seguridad,$user_selected->getCedula());
    //************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName() . '/usuario/showEmailAccount?emailaccount_id=' . $email_account->getPrimaryKey());
  }

  public function executeUploads()
  {
    foreach ($this->getRequest()->getFiles() as $file) 	
    {
    	$dirRaiz = ParametroPeer::retrieveByPk(9)->getValortexto();
    	$dirFotos  = ParametroPeer::retrieveByPk(38)->getValortexto();
    	$dirTemp  = ParametroPeer::retrieveByPk(65)->getValortexto();
    	//********************************************************************************
    	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    	$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
    	$entidad_text = trim($usuario->getRegional()->getEntidad()->getDirectorioName());
    	$regional_text = trim($usuario->getRegional()->getDirectorioName());
    	$entidad_text = $entidad_text ? $entidad_text : "";//.'/'.$regional_text;
    	$path_directorio = $dirRaiz.$entidad_text.DIRECTORY_SEPARATOR.$dirTemp;
		//********************************************************************************
        if(trim($this->getRequestParameter('efirma'))){
            $dirFirmas = "firmas_electronicas";
            $path_directorio = $path_directorio.DIRECTORY_SEPARATOR.$dirFirmas;
            $this->efirma = trim($this->getRequestParameter('efirma'));
        }
		//********************************************************************************
    	//$cons    = $this->getNewConsecutivo();
        $file_vars = pathinfo($file['name']);
		$extension = $file_vars['extension'];
		//********************************************************************************
        $util_simad = new simad_util();
        $fileName = $util_simad->clean_name_file($file_vars);
		$fileName = sprintf("%s.%s",md5($fileName.date("YmdGis")),$extension);
        //********************************************************************************
        $directorio = simad_util::createPath($path_directorio);
        @move_uploaded_file($file['tmp_name'], $directorio.DIRECTORY_SEPARATOR.$fileName);
        $this->fileName = $fileName;
    }
    }	         

  public function getNewConsecutivo()
	{
		$cons = ParametroPeer::retrieveByPk(8);
		$regId = $cons->getValorNumerico();
		if($regId > 0){
			$cons->setValorNumerico($regId+1);
			$cons->save();
		}
		return $regId;		
	}
  
