  public function executeCreate()
  { 
  	$this->verificaPrilegio("usuario/create");
    $this->usuario = new Usuario();
    $this->entidad_select = 0;
    $this->cargosUsuarioId = 0;
    $this->tipo_proceso_com = TipoProcesoComPeer::getOrdenTipoProcesoCom();
    //*********************************** PERMISOS ********************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $usuario_object = UsuarioPeer::retrieveByPK($usuariologuiado);
    //*********************************** ENTIDAD ********************************************
    if(!$this->getUser()->checkPerm("LISTAR_USUARIOS_TODAS_ENTIDADES", $usuariologuiado)){
      $ce = new Criteria();
      $ce->setDistinct();
      $ce->addJoin(EntidadPeer::ENTIDAD_ID, RegionalPeer::ENTIDAD_ID);
      $ce->add(RegionalPeer::ENTIDAD_ID,$usuario_object->getRegional()->getEntidadId());
      $this->entidades_list = EntidadPeer::doSelect($ce);
    }else{
      $this->entidades_list = EntidadPeer::doSelect(new Criteria());
    }
    //****************************************************************************************
    $this->roles_list = RolPeer::getOrdenarRol();
    $this->current_roles = 0;
    //*****************************************************************************************
    $this->setTemplate('edit');
  }

  public function executeFirmaStatus()
	{
		$config_advanced_firma = $this->getUser()->checkPerm("CONFIGURACION_ADVANCED_FIRMA");
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $this->tipoconfig = "";
    //***************************************************************************************
		if($config_advanced_firma){
      $usuario = UsuarioPeer::retrieveByPk($this->getRequestParameter('usuario_id'));
      HistUsuarioPeer::addNewHistUser($usuario->toArray(),$usuariologuiado,$usuario->getPrimaryKey());
      if($this->getRequestParameter('firmamecanica')){
        $usuario->setUseFirmaElectronica($usuario->getUseFirmaElectronica() ? 0 : 1);
        $usuario->save();
        $this->getUser()->setAttribute('firma_mecanica',$usuario->getUseFirmaElectronica(), 'subscriber');
        $this->tipoconfig = 'firma_mecanica';
      }elseif($this->getRequestParameter('firmadigital')){
        $usuario->setFirmaDigital($usuario->getFirmaDigital() ? 0 : 1);
        $usuario->save();
        $this->getUser()->setAttribute('firma_digital',$usuario->getFirmaDigital(),  'subscriber');
        $this->tipoconfig = 'firma_digital';
      }elseif($this->getRequestParameter('firmadesatendida')){
        $usuario->setFirmaDesatendida($usuario->getFirmaDesatendida() ? 0 : 1);
        $usuario->save();
        $this->getUser()->setAttribute('firma_desatendida',$usuario->getFirmaDesatendida(), 'subscriber');
        $this->tipoconfig = 'firma_desatendida';
      }
      //***************************************************************************************
      $this->usuario = $usuario;
		}else{
			return sfView::NONE;
		}
	}

  public function executeEdit()
  {
  	$this->verificaPrilegio("usuario/edit");
    $cargosUsuarioId = "";
    $this->usuario = UsuarioPeer::retrieveByPk($this->getRequestParameter('usuario_id'));
    $this->forward404Unless($this->usuario);
    //***************************************************************************************
    $crCargo = new Criteria();
	  $crCargo->add(CargoUsuarioPeer::USUARIO_ID, $this->getRequestParameter('usuario_id'));
    $crCargo->add(CargoUsuarioPeer::ES_PRINCIPAL,1);
    $objCargoUsuario = CargoUsuarioPeer::doSelect($crCargo);
    foreach($objCargoUsuario as $cargosUsuarios){
        $cargosUsuarioId = $cargosUsuarios->getCargoId();
    }
    //*********************************** PERMISOS *******************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $usuario_object = UsuarioPeer::retrieveByPK($usuariologuiado);
    $this->tipo_proceso_com = TipoProcesoComPeer::getOrdenTipoProcesoCom();
    //*********************************** ENTIDAD ********************************************
    $ce = new Criteria();
    $ce->setDistinct();
    $ce->addJoin(EntidadPeer::ENTIDAD_ID, RegionalPeer::ENTIDAD_ID);
    if(!$this->getUser()->checkPerm("LISTAR_USUARIOS_TODAS_ENTIDADES", $usuariologuiado)){    	
    	$ce->add(RegionalPeer::ENTIDAD_ID,$usuario_object->getRegional()->getEntidadId());
    }
    $this->entidades_list = EntidadPeer::doSelect($ce);
    //*********************************** REGIONAL *******************************************
    $cr = new Criteria();
    $cr->setDistinct();
    if(!$this->getUser()->checkPerm("LISTAR_USUARIOS_TODAS_REGIONALES", $usuariologuiado)){
      $cr->add(RegionalPeer::REGIONAL_ID,$usuario_object->getRegionalId());
    }
    $ce->add(RegionalPeer::ENTIDAD_ID,$usuario_object->getRegional()->getEntidadId());
    $this->regionales_list = RegionalPeer::doSelect($cr);
    //*********************************** DEPENDENCIA ****************************************
    $cd = new Criteria();
    $cd->setDistinct();
    $cd->add(DependenciaPeer::ENTIDAD_ID,$usuario_object->getRegional()->getEntidadId());
