    $entidad_text = preg_replace('#/+#','/',$entidad_text.'/'.$regional_text);
    $alias_tmp = $dirAlias.$entidad_text.'/';
    $alias_directorio = preg_replace('#/+#','/',$alias_tmp.'/'.$dirFotos.'/');
    $target = preg_replace('#/+#','/',$dirRaiz.$entidad_text.'/'.$dirFotos);
    $sourcetmp = $dirRaiz.trim($usuario->getRegional()->getEntidad()->getDirectorioName()).DIRECTORY_SEPARATOR.$dirTemp;
